INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15801, 'តាមនិយមន័យ បន្ទាត់ពីរក្នុងលំហហៅថាអរតូកូណាល់គ្នា កាលណា ៖', NULL, '["បន្ទាត់ទាំងពីរស្របគ្នា", "បន្ទាត់ទាំងពីរកាត់គ្នាក្នុងប្លង់", "មុំរវាងបន្ទាត់ទាំងពីរជាមុំកែង (90 ដឺក្រេ)", "បន្ទាត់ទាំងពីរគ្មានចំណុចរួម"]', 2, NULL, 1, 'mcq', 'បន្ទាត់ពីរអរតូកូណាល់គ្នាកាលណាមុំរវាងពួកវាស្មើនឹង 90 ដឺក្រេ (អាចកាត់គ្នា ឬជាបន្ទាត់ទ្វេរ)។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'easy', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15802, 'បន្ទាត់មួយកែងនឹងប្លង់មួយ កាលណា ៖', NULL, '["បន្ទាត់នោះអរតូកូណាល់នឹងគ្រប់បន្ទាត់ទាំងអស់នៅក្នុងប្លង់នោះ", "បន្ទាត់នោះកែងនឹងបន្ទាត់តែមួយគត់ក្នុងប្លង់", "បន្ទាត់នោះស្ថិតក្នុងប្លង់", "បន្ទាត់នោះស្របនឹងប្លង់"]', 0, NULL, 1, 'mcq', 'បន្ទាត់កែងនឹងប្លង់កាលណាវាអរតូកូណាល់នឹងគ្រប់បន្ទាត់ក្នុងប្លង់ d ⊥ (P) <=> ∀a ⊂ (P), d ⊥ a។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'easy', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15803, 'ប្លង់មេដ្យាទ័រនៃអង្កត់ \([AB]\) គឺជាប្លង់ដែល ៖', NULL, '["កែងនឹងអង្កត់ AB ត្រង់ចំណុចកណ្តាល", "កាត់តាមចុង A នៃអង្កត់", "ស្របនឹងអង្កត់ AB", "កាត់តាមចុង B នៃអង្កត់"]', 0, NULL, 1, 'mcq', 'ប្លង់មេដ្យាទ័រនៃអង្កត់មួយជាប្លង់កែងនឹងអង្កត់នោះត្រង់ចំណុចកណ្តាល។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'easy', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15804, 'ប្លង់ពីរហៅថាកែងគ្នា \((P) \perp (Q)\) កាលណា ៖', NULL, '["ប្លង់ទាំងពីរគ្មានចំណុចរួម", "ប្លង់ទាំងពីរកាត់គ្នាតាមបន្ទាត់មួយ", "ប្លង់មួយមានផ្ទុកបន្ទាត់ដែលកែងនឹងប្លង់មួយទៀត", "ប្លង់ទាំងពីរស្របគ្នា"]', 2, NULL, 1, 'mcq', '(P) ⊥ (Q) កាលណាមានបន្ទាត់ a ⊂ (P) ដែល a ⊥ (Q)។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'easy', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15805, 'ចំណោលកែងនៃចំណុច \(M\) មកលើប្លង់ \((P)\) គឺជា ៖', NULL, '["ចំណុចណាមួយក្នុងប្លង់ (P)", "ចំណុចប្រសព្វរវាងប្លង់ (P) និងបន្ទាត់កែងគូសចេញពី M មកលើ (P)", "ចំណុចកណ្តាលនៃប្លង់", "ចំណុច M ខ្លួនឯងជានិច្ច"]', 1, NULL, 1, 'mcq', 'ចំណោលកែងនៃចំណុចលើប្លង់ជាជើងចំណោលកែង M'' នៃបន្ទាត់ MM'' ⊥ (P)។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'easy', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15806, 'រូបមន្តមាឌនៃពីរ៉ាមីតដែលមានផ្ទៃក្រឡាបាត \(B\) និងកម្ពស់ \(h\) គឺ ៖', NULL, '["\\(V = \\frac{4}{3}Bh\\)", "\\(V = Bh\\)", "\\(V = \\frac{1}{3}Bh\\)", "\\(V = \\frac{1}{2}Bh\\)"]', 2, NULL, 1, 'mcq', 'មាឌពីរ៉ាមីត V = (1/3) B h។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'easy', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15807, 'ដើម្បីបង្ហាញថាបន្ទាត់មួយកែងនឹងប្លង់មួយ គេគ្រាន់តែបង្ហាញថាបន្ទាត់នោះអរតូកូណាល់នឹង ៖', NULL, '["បន្ទាត់ប្រសព្វគ្នាពីរនៅក្នុងប្លង់នោះ", "បន្ទាត់ស្របគ្នាពីរក្នុងប្លង់", "បន្ទាត់តែមួយក្នុងប្លង់", "បន្ទាត់បីស្របគ្នាក្នុងប្លង់"]', 0, NULL, 1, 'mcq', 'ទ្រឹស្តីបទទី ១ ៖ បើបន្ទាត់មួយអរតូកូណាល់នឹងបន្ទាត់ប្រសព្វគ្នាពីរក្នុងប្លង់ នោះវាកែងនឹងប្លង់។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'easy', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15808, 'បើ \(A''B''\) ជាចំណោលកែងនៃអង្កត់ \(AB\) លើប្លង់ \((P)\) ហើយ \(lpha\) ជាមុំរវាង \(AB\) និង \((P)\) នោះ ៖', NULL, '["\\(A''B'' = AB \tan\u0007lpha\\)", "\\(A''B'' = \\frac{AB}{\\cos\\alpha}\\)", "\\(A''B'' = AB \\cos\u0007lpha\\)", "\\(A''B'' = AB \\sin\u0007lpha\\)"]', 2, NULL, 1, 'mcq', 'រូបមន្តប្រវែងចំណោលកែង A''B'' = AB cos(α)។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'easy', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15809, 'រូបមន្តមាឌនៃគូបដែលមានទ្រនុង \(a\) គឺ ៖', NULL, '["\\(V = 3a\\)", "\\(V = a^3\\)", "\\(V = 6a^2\\)", "\\(V = a^2\\)"]', 1, NULL, 1, 'mcq', 'មាឌគូប V = a^3។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'easy', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15810, 'បើបន្ទាត់ពីរ \(d\) និង \(d''\) កែងនឹងប្លង់ \((P)\) តែមួយ នោះ ៖', NULL, '["\\(d \text{ និង } d'' \text{ ជាបន្ទាត់ទ្វេរ}\\)", "\\(d \\parallel d''\\)", "\\(d \\cap d'' = \\{O\\}\\)", "\\(d \\perp d''\\)"]', 1, NULL, 1, 'mcq', 'បន្ទាត់ពីរដែលកែងនឹងប្លង់តែមួយ តែងតែស្របគ្នាជានិច្ច (ទ្រឹស្តីបទទី ២)។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'easy', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15811, 'តាមទ្រឹស្តីបទបីបន្ទាត់កែង បើ \(AB \perp (P)\) ត្រង់ \(B\) ហើយ \(BO \perp a\) (\(a \subset (P)\)) ត្រង់ \(O\) នោះ ៖', NULL, '["\\(AO \\parallel a\\)", "\\(AO \\perp BO\\)", "\\(AO \\perp a\\)", "\\(AO \\subset (P)\\)"]', 2, NULL, 2, 'mcq', 'ទ្រឹស្តីបទបីបន្ទាត់កែង AB ⊥ (P) និង BO ⊥ a ⊂ (P) => AO ⊥ a។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15812, 'បើ \(AB \perp (P)\) ត្រង់ \(B\) ហើយ \(AO \perp a\) (\(a \subset (P)\)) ត្រង់ \(O\) នោះ ៖', NULL, '["\\(BO \\perp AB\\)", "\\(BO \\parallel a\\)", "\\(BO \\perp a\\)", "\\(BO = AO\\)"]', 2, NULL, 2, 'mcq', 'ទ្រឹស្តីបទច្រាសនៃបីបន្ទាត់កែង AB ⊥ (P) និង AO ⊥ a ⊂ (P) => BO ⊥ a។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15813, 'ប្រលេពីប៉ែតកែងមានវិមាត្រ \(a = 3	ext{ cm}, b = 4	ext{ cm}, c = 12	ext{ cm}\)។ ប្រវែងអង្កត់ទ្រូងលំហ \(d\) គឺ ៖', NULL, '["\\(12\text{ cm}\\)", "\\(14\text{ cm}\\)", "\\(15\text{ cm}\\)", "\\(13\text{ cm}\\)"]', 3, NULL, 2, 'mcq', 'd = √(a^2 + b^2 + c^2) = √(9 + 16 + 144) = √169 = 13 cm។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15814, 'បើផ្ទៃក្រឡាសរុបនៃគូបមួយស្មើនឹង \(96	ext{ cm}^2\) នោះមាឌនៃគូបគឺ ៖', NULL, '["\\(16\text{ cm}^3\\)", "\\(64\text{ cm}^3\\)", "\\(128\text{ cm}^3\\)", "\\(32\text{ cm}^3\\)"]', 1, NULL, 2, 'mcq', '6a^2 = 96 => a^2 = 16 => a = 4 cm; មាឌ V = 4^3 = 64 cm^3។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15815, 'ក្នុងគូប \(ABCD.EFGH\) មុំរវាងបន្ទាត់ \(AC\) និង \(BD\) គឺ ៖', NULL, '["\\(60^\\circ\\)", "\\(0^\\circ\\)", "\\(45^\\circ\\)", "\\(90^\\circ\\)"]', 3, NULL, 2, 'mcq', 'បាត ABCD ជាការេ នាំឱ្យអង្កត់ទ្រូងទាំងពីរ AC ⊥ BD (មុំ 90 ដឺក្រេ)។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15816, 'ក្នុងគូប \(ABCD.EFGH\) បន្ទាត់ \(AE\) កែងនឹងប្លង់ណា?', NULL, '["\\((ABCD)\\)", "\\((ABFE)\\)", "\\((BDHF)\\)", "\\((ADHE)\\)"]', 0, NULL, 2, 'mcq', 'AE ⊥ AB និង AE ⊥ AD នាំឱ្យ AE ⊥ (ABCD)។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15817, 'ក្នុងគូប \(ABCD.A''B''C''D''\) ប្លង់មេដ្យាទ័រនៃអង្កត់ \([AC]\) គឺប្លង់ ៖', NULL, '["\\((A''B''C''D'')\\)", "\\((ACC''A'')\\)", "\\((BDD''B'')\\)", "\\((ABCD)\\)"]', 2, NULL, 2, 'mcq', 'BA = BC, DA = DC, B''A = B''C'' នាំឱ្យប្លង់ (BDD''B'') ជាប្លង់មេដ្យាទ័រនៃ [AC]។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15818, 'ក្នុងគូប \(ABCD.EFGH\) មុំរវាងប្លង់មុខកាត់ \((AFGD)\) និងប្លង់បាត \((ABCD)\) គឺ ៖', NULL, '["\\(90^\\circ\\)", "\\(45^\\circ\\)", "\\(30^\\circ\\)", "\\(60^\\circ\\)"]', 1, NULL, 2, 'mcq', 'ប្រសព្វគឺ AD; BA ⊥ AD និង FA ⊥ AD; មុំរវាងប្លង់ទាំងពីរគឺ ∠FAB = 45 ដឺក្រេ (ក្នុងមុខការេ ABFE)។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15819, 'ត្រីកោណ \(ABC\) មានផ្ទៃក្រឡា \(S = 50	ext{ cm}^2\)។ ចំណោលកែងរបស់វាលើប្លង់ \((P)\) បង្កើតបានមុំ \(lpha = 60^\circ\)។ ផ្ទៃក្រឡាចំណោល \(S''\) គឺ ៖', NULL, '["\\(50\text{ cm}^2\\)", "\\(100\text{ cm}^2\\)", "\\(25\text{ cm}^2\\)", "\\(25\\sqrt{3}\text{ cm}^2\\)"]', 2, NULL, 2, 'mcq', 'S'' = S cos(60°) = 50 x 0.5 = 25 cm^2។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15820, 'អង្កត់ \(AB = 10	ext{ cm}\) បង្កើតបានមុំ \(lpha = 45^\circ\) ជាមួយប្លង់ \((P)\)។ ប្រវែងចំណោលកែង \(A''B''\) លើ \((P)\) គឺ ៖', NULL, '["\\(10\\sqrt{2}\text{ cm}\\)", "\\(5\text{ cm}\\)", "\\(5\\sqrt{2}\text{ cm}\\)", "\\(5\\sqrt{3}\text{ cm}\\)"]', 2, NULL, 2, 'mcq', 'A''B'' = AB cos(45°) = 10 x (√2 / 2) = 5√2 cm។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15821, 'ពីរ៉ាមីត \(S.ABCD\) មានបាតជាការេជ្រុង \(6	ext{ cm}\) និងកម្ពស់ \(SO = 8	ext{ cm}\)។ មាឌនៃពីរ៉ាមីតគឺ ៖', NULL, '["\\(288\text{ cm}^3\\)", "\\(96\text{ cm}^3\\)", "\\(144\text{ cm}^3\\)", "\\(48\text{ cm}^3\\)"]', 1, NULL, 2, 'mcq', 'V = (1/3) x 6^2 x 8 = (1/3) x 36 x 8 = 96 cm^3។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15822, 'កោណមួយមានកាំបាត \(r = 3	ext{ cm}\) និងកម្ពស់ \(h = 4	ext{ cm}\)។ ប្រវែងទ្រនុងខាង (ជនេត្រ \(a\)) គឺ ៖', NULL, '["\\(6\text{ cm}\\)", "\\(7\text{ cm}\\)", "\\(5\text{ cm}\\)", "\\(\\sqrt{7}\text{ cm}\\)"]', 2, NULL, 2, 'mcq', 'a = √(r^2 + h^2) = √(9 + 16) = √25 = 5 cm។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15823, 'ស៊ីឡាំងមួយមានកាំបាត \(r = 2	ext{ cm}\) និងកម្ពស់ \(h = 5	ext{ cm}\)។ មាឌនៃស៊ីឡាំងគឺ ៖', NULL, '["\\(25\\pi\text{ cm}^3\\)", "\\(20\\pi\text{ cm}^3\\)", "\\(40\\pi\text{ cm}^3\\)", "\\(10\\pi\text{ cm}^3\\)"]', 1, NULL, 2, 'mcq', 'V = π r^2 h = π x 4 x 5 = 20π cm^3។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15824, 'ក្នុងគូប \(ABCD.EFGH\) មុំរវាងបន្ទាត់ \(AC\) និង \(FH\) គឺ ៖', NULL, '["\\(90^\\circ\\)", "\\(60^\\circ\\)", "\\(0^\\circ\\)", "\\(45^\\circ\\)"]', 0, NULL, 2, 'mcq', 'ដោយ FH // BD ហើយ AC ⊥ BD នាំឱ្យ AC ⊥ FH (អរតូកូណាល់ មុំ 90 ដឺក្រេ)។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15825, 'ចតុមុខ \(OABC\) មាន \(OA, OB, OC\) កែងគ្នាពីរៗត្រង់ \(O\) ដោយ \(OA = a, OB = b, OC = c\)។ មាឌនៃចតុមុខគឺ ៖', NULL, '["\\(\\frac{1}{2}abc\\)", "\\(\\frac{1}{6}abc\\)", "\\(abc\\)", "\\(\\frac{1}{3}abc\\)"]', 1, NULL, 3, 'mcq', 'បាត OAB កែងត្រង់ O មានផ្ទៃ ab/2; កម្ពស់ OC = c => V = (1/3)(ab/2)c = abc/6។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'hard', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15826, 'ចតុមុខ \(OABC\) មាន \(OA, OB, OC\) កែងគ្នាពីរៗត្រង់ \(O\)។ បើ \(OH \perp (ABC)\) នោះទំនាក់ទំនងរវាងកម្ពស់ \(OH\) និងជ្រុងគឺ ៖', NULL, '["\\(OH^2 = OA^2 + OB^2 + OC^2\\)", "\\(\\frac{1}{OH^2} = \\frac{1}{OA^2} + \\frac{1}{OB^2} + \\frac{1}{OC^2}\\)", "\\(\\frac{1}{OH} = \\frac{1}{OA} + \\frac{1}{OB} + \\frac{1}{OC}\\)", "\\(OH = \\frac{OA + OB + OC}{3}\\)"]', 1, NULL, 3, 'mcq', 'ទ្រឹស្តីបទពីតាក័រក្នុងចតុមុខត្រីកែង 1/OH^2 = 1/OA^2 + 1/OB^2 + 1/OC^2។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'hard', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15827, 'ចតុមុខនិយ័ត \(ABCD\) ជ្រុង \(a\)។ មុំរវាងទ្រនុងឈមពីរ \(AB\) និង \(CD\) គឺ ៖', NULL, '["\\(90^\\circ\\)", "\\(45^\\circ\\)", "\\(60^\\circ\\)", "\\(0^\\circ\\)"]', 0, NULL, 3, 'mcq', 'ក្នុងចតុមុខនិយ័ត គ្រប់គូនៃទ្រនុងឈមទាំងអស់សុទ្ធតែអរតូកូណាល់គ្នា (90 ដឺក្រេ)។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'hard', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15828, 'ត្រីកោណសម័ង្ស \(ABC\) ជ្រុង \(a\) ធ្វើចំណោលកែងលើប្លង់ \((P)\) បានត្រីកោណ \(A''B''C''\) ដែលមានផ្ទៃ \(\frac{a^2\sqrt{3}}{8}\)។ មុំរវាងប្លង់ \((ABC)\) និង \((P)\) គឺ ៖', NULL, '["\\(45^\\circ\\)", "\\(30^\\circ\\)", "\\(60^\\circ\\)", "\\(90^\\circ\\)"]', 2, NULL, 3, 'mcq', 'S = a^2√3 / 4; S'' = S cos(α) => cos(α) = (a^2√3/8) / (a^2√3/4) = 1/2 => α = 60°។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'hard', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15829, 'បើ \((P) \perp (R)\) ហើយ \((Q) \parallel (R)\) នោះទំនាក់ទំនងរវាង \((P)\) និង \((Q)\) គឺ ៖', NULL, '["\\((P) \\parallel (Q)\\)", "\\((P) \\perp (Q)\\)", "\\((P) \\cap (Q) = \\emptyset\\)", "\\((P) \\equiv (Q)\\)"]', 1, NULL, 3, 'mcq', 'ប្លង់ដែលកែងនឹងប្លង់មួយ ត្រូវតែកែងនឹងគ្រប់ប្លង់ដែលស្របនឹងប្លង់នោះ។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'hard', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15830, 'គូបមួយមានអង្កត់ទ្រូងលំហ \(d = 6\sqrt{3}	ext{ cm}\)។ មាឌនៃគូបនេះគឺ ៖', NULL, '["\\(108\text{ cm}^3\\)", "\\(36\text{ cm}^3\\)", "\\(72\text{ cm}^3\\)", "\\(216\text{ cm}^3\\)"]', 3, NULL, 3, 'mcq', 'd = a√3 = 6√3 => a = 6 cm; V = 6^3 = 216 cm^3។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'hard', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15831, 'កោណមួយត្រូវបានកាត់ដោយប្លង់ស្របនឹងបាតត្រង់ពាក់កណ្តាលកម្ពស់ \(h/2\)។ ផលធៀបមាឌកោណតូចខាងលើធៀបនឹងកោណធំដើមគឺ ៖', NULL, '["\\(\\frac{1}{2}\\)", "\\(\\frac{1}{4}\\)", "\\(\\frac{1}{16}\\)", "\\(\\frac{1}{8}\\)"]', 3, NULL, 3, 'mcq', 'ផលធៀបវិមាត្រ k = 1/2 នាំឱ្យផលធៀបមាឌគឺ k^3 = 1/8។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'hard', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15832, 'ក្នុងការសាងសង់ផ្ទះ ជាងសំណង់ប្រើ «ខ្សែបន្ទាត់តម្រង់ទម្ងន់» (Plumb line) ដើម្បីតម្រង់ជញ្ជាំង។ គោលការណ៍ធរណីមាត្រនៃខ្សែនេះគឺ ៖', NULL, '["ខ្សែមិនទាក់ទងនឹងប្លង់ដី", "ខ្សែតម្រង់ទម្ងន់តែងតែកែងនឹងប្លង់ដីរាបស្មើជានិច្ច", "ខ្សែស្របនឹងប្លង់ដី", "ខ្សែបង្កើតមុំ ៤៥ ដឺក្រេនឹងដី"]', 1, NULL, 3, 'mcq', 'ទិសដៅទំនាញផែនដីបង្កើតបានបន្ទាត់កែងនឹងប្លង់ទឹកស្ងប់ (ប្លង់ផ្តេក) ជួយឱ្យជញ្ជាំងឈរត្រង់កែងនឹងកម្រាល។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'pisa', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15833, 'ទ្វារបន្ទប់មួយបង្វិលជុំវិញត្រចៀកទ្វារបញ្ឈរ \(AB\)។ នៅគ្រប់ទីតាំងនៃការបើកទ្វារ បន្ទាត់ត្រចៀកទ្វារ \(AB\) ៖', NULL, '["កាត់កម្រាលបន្ទប់ក្នុងមុំប្រែប្រួល", "កែងនឹងប្លង់កម្រាលបន្ទប់ជានិច្ច", "ស្របនឹងកម្រាលបន្ទប់", "កែងនឹងផ្ទៃទ្វារ"]', 1, NULL, 3, 'mcq', 'អ័ក្សបង្វិលនៃទ្វារជាបន្ទាត់បញ្ឈរកែងនឹងប្លង់កម្រាល ធានាឱ្យទ្វារបើកបិទដោយរលូនមិនកកិតនឹងកម្រាល។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'pisa', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15834, 'ដំបូលសាលប្រជុំរាងជាត្រីកោណទ្រេតបង្កើតមុំ \(30^\circ\) ធៀបនឹងប្លង់កម្រាលពិដាន។ បើផ្ទៃក្រឡាពិដានខាងក្រោមស្មើ \(200	ext{ m}^2\) នោះផ្ទៃក្រឡាក្បឿងដំបូលពិតប្រាកដគឺ ៖', NULL, '["\\(200\text{ m}^2\\)", "\\(100\text{ m}^2\\)", "\\(\\frac{400}{\\sqrt{3}}\text{ m}^2 \u0007pprox 230.9\text{ m}^2\\)", "\\(150\text{ m}^2\\)"]', 2, NULL, 3, 'mcq', 'S_ពិដាន = S_ដំបូល x cos(30°) => S_ដំបូល = 200 / (√3/2) = 400/√3 ≈ 230.9 m^2។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'pisa', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15835, 'បង្គោលភ្លើងស្តុបចរាចរណ៍មួយដើមឈរកែងនឹងទ្រូងផ្លូវរាបស្មើ។ ពេលថ្ងៃត្រង់ត្រង់ក្បាល (ព្រះអាទិត្យនៅចំណុចខ្ពស់បំផុត) ស្រមោលនៃបង្គោលលើដី ៖', NULL, '["មានប្រវែងស្មើនឹងកម្ពស់បង្គោល", "មិនអាចមើលឃើញទេ", "រួមតូចស្ទើរតែក្លាយជាចំណុចមួយគត់ (ជើងចំណោលកែង)", "វែងជាងកម្ពស់បង្គោលពីរដង"]', 2, NULL, 3, 'mcq', 'កាំរស្មីព្រះអាទិត្យស្របនឹងបង្គោលកែង ធ្វើឱ្យចំណោលកែងនៃអង្កត់បញ្ឈររួមតូចជាចំណុចមួយលើប្លង់ដី។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'pisa', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15836, 'ធុងស្តុកទឹកភ្លៀងរាងស៊ីឡាំងបរិវត្តមួយមានកម្ពស់ \(2	ext{ m}\) និងអង្កត់ផ្ចិតបាត \(2	ext{ m}\) (កាំ \(1	ext{ m}\))។ ចំណុះទឹកអតិបរមាគិតជាលីត្រ (យក \(\pi pprox 3.14\)) គឺ ៖', NULL, '["ប្រហែល ៦២៨០ លីត្រ", "ប្រហែល ១២៥៦០ លីត្រ", "ប្រហែល ៦២៨ លីត្រ", "ប្រហែល ៣១៤០ លីត្រ"]', 0, NULL, 3, 'mcq', 'V = π r^2 h = 3.14 x 1^2 x 2 = 6.28 m^3 = 6280 លីត្រ (ព្រោះ 1 m^3 = 1000 លីត្រ)។', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'pisa', 1, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15837, 'ចូរឱ្យនិយមន័យនៃបន្ទាត់កែងនឹងប្លង់ និងសរសេរលក្ខខណ្ឌទ្រឹស្តីបទទី ១ ដើម្បីបង្ហាញថាបន្ទាត់មួយកែងនឹងប្លង់។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរនិយមន័យ ៖ បន្ទាត់មួយកែងនឹងប្លង់មួយ កាលណាវាកែង (អរតូកូណាល់) នឹងគ្រប់បន្ទាត់ទាំងអស់ក្នុងប្លង់នោះ (១ ពិន្ទុ) (1 ពិន្ទុ)
សរសេរបម្រាប់បន្ទាត់ទី ១ ៖ d ⊥ a ដោយ a ⊂ (P) (១ ពិន្ទុ) (1 ពិន្ទុ)
សរសេរបម្រាប់បន្ទាត់ទី ២ ៖ d ⊥ b ដោយ b ⊂ (P) (១ ពិន្ទុ) (1 ពិន្ទុ)
សរសេរបម្រាប់ប្រសព្វ ៖ a និង b ត្រូវតែជាបន្ទាត់ប្រសព្វគ្នា a ∩ b = {O} (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ បើ d ⊥ a, d ⊥ b និង a ∩ b = {O} នោះ d ⊥ (P) (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'easy', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15838, 'ចូរបង្ហាញទ្រឹស្តីបទបីបន្ទាត់កែង ៖ បើបន្ទាត់ \(AB \perp (P)\) ត្រង់ \(B\) ហើយ \(BO \perp a\) (\(a \subset (P)\)) ត្រង់ \(O\) នោះ \(AO \perp a\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ទាញរក AB ⊥ a ៖ ដោយ AB ⊥ (P) និង a ⊂ (P) នាំឱ្យ AB ⊥ a ឬ a ⊥ AB (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក a ⊥ BO ៖ តាមបម្រាប់ BO ⊥ a នាំឱ្យ a ⊥ BO (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក a ⊥ (ABO) ៖ បន្ទាត់ a កែងនឹងបន្ទាត់កាត់គ្នាពីរ AB និង BO នៃប្លង់ (ABO) នាំឱ្យ a ⊥ (ABO) (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរកភាពកែងនឹង AO ៖ ដោយ AO ⊂ (ABO) និង a ⊥ (ABO) នាំឱ្យ a ⊥ AO (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ ដូច្នេះ AO ⊥ a ត្រូវបានស្រាយបញ្ជាក់ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15839, 'គេឱ្យប្រលេពីប៉ែតកែង \(ABCD.EFGH\) មានវិមាត្រ \(AB = a, BC = b, AE = c\)។ ចូរស្រាយបញ្ជាក់ថាអង្កត់ទ្រូងលំហ \(EC = \sqrt{a^2 + b^2 + c^2}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'បង្ហាញ BC ⊥ (ABFE) ៖ BC ⊥ AB និង BC ⊥ BF នាំឱ្យ BC ⊥ (ABFE) (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក ΔEBC កែង ៖ EB ⊂ (ABFE) នាំឱ្យ BC ⊥ EB ដូច្នេះ ΔEBC កែងត្រង់ B (១ ពិន្ទុ) (1 ពិន្ទុ)
អនុវត្តពីតាក័រក្នុង ΔEBC ៖ EC^2 = EB^2 + BC^2 = EB^2 + b^2 (១ ពិន្ទុ) (1 ពិន្ទុ)
អនុវត្តពីតាក័រក្នុង ΔEAB ៖ ΔEAB កែងត្រង់ A នាំឱ្យ EB^2 = AE^2 + AB^2 = c^2 + a^2 (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋានរូបមន្ត ៖ EC^2 = a^2 + b^2 + c^2 => EC = √(a^2 + b^2 + c^2) (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15840, 'គេឱ្យចតុមុខនិយ័ត \(ABCD\) មួយ។ ចូរបង្ហាញថាទ្រនុង \(CD\) ស្ថិតនៅក្នុងប្លង់មេដ្យាទ័រនៃអង្កត់ \([AB]\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់លក្ខណៈចតុមុខនិយ័ត ៖ គ្រប់ជ្រុងទាំងអស់ស្មើគ្នា AC = BC = AD = BD = CD = a (១ ពិន្ទុ) (1 ពិន្ទុ)
ពិនិត្យចំណុច C ៖ ដោយ CA = CB នាំឱ្យ C ស្មើចម្ងាយពី A និង B (១ ពិន្ទុ) (1 ពិន្ទុ)
ពិនិត្យចំណុច D ៖ ដោយ DA = DB នាំឱ្យ D ស្មើចម្ងាយពី A និង B (១ ពិន្ទុ) (1 ពិន្ទុ)
អនុវត្តលក្ខណៈប្លង់មេដ្យាទ័រ ៖ គ្រប់ចំណុចស្មើចម្ងាយពី A និង B ស្ថិតក្នុងប្លង់មេដ្យាទ័រ (P) នៃ [AB] (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ C ∈ (P) និង D ∈ (P) នាំឱ្យបន្ទាត់ CD ⊂ (P) ស្ថិតក្នុងប្លង់មេដ្យាទ័រនៃ [AB] (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15841, 'ត្រីកោណ \(ABC\) មានផ្ទៃក្រឡា \(S = 60	ext{ cm}^2\) ធ្វើចំណោលកែងលើប្លង់ \((P)\) បានត្រីកោណ \(A''B''C''\) មានផ្ទៃ \(S'' = 30\sqrt{3}	ext{ cm}^2\)។ ចូរគណនាមុំ \(lpha\) រវាងប្លង់ \((ABC)\) និងប្លង់ \((P)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេររូបមន្តចំណោលកែងផ្ទៃ ៖ S'' = S cos(α) (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរកកន្សោម cos(α) ៖ cos(α) = S'' / S (១ ពិន្ទុ) (1 ពិន្ទុ)
ជំនួសតម្លៃលេខ ៖ cos(α) = (30√3) / 60 = √3 / 2 (១ ពិន្ទុ) (1 ពិន្ទុ)
ដោះស្រាយរកមុំ α ៖ ដោយ 0° ≤ α ≤ 90° នាំឱ្យ α = 30° (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ មុំរវាងប្លង់ត្រីកោណ ABC និងប្លង់ (P) គឺ 30 ដឺក្រេ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'medium', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15842, 'គេឱ្យពីរ៉ាមីត \(S.ABCD\) មានបាត \(ABCD\) ជាការេជ្រុង \(a\) និងទ្រនុងចំហៀង \(SB \perp (ABCD)\) ដោយ \(SB = a\)។ បង្ហាញថា \(AD \perp (SAB)\) រួចគណនាមាឌពីរ៉ាមីត។', NULL, '[]', 0, NULL, 5, 'writing', 'ទាញរក AD ⊥ AB ៖ ដោយ ABCD ជាការេ នាំឱ្យ AD ⊥ AB (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក AD ⊥ SB ៖ ដោយ SB ⊥ (ABCD) និង AD ⊂ (ABCD) នាំឱ្យ SB ⊥ AD ឬ AD ⊥ SB (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក AD ⊥ (SAB) ៖ AD កែងនឹងបន្ទាត់ប្រសព្វ AB និង SB នាំឱ្យ AD ⊥ (SAB) (១ ពិន្ទុ) (1 ពិន្ទុ)
គណនាផ្ទៃក្រឡាបាត ៖ B = S_ABCD = a^2 (១ ពិន្ទុ) (1 ពិន្ទុ)
គណនាមាឌពីរ៉ាមីត ៖ V = (1/3) x B x SB = (1/3) x a^2 x a = a^3 / 3 (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'hard', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15843, 'ចតុមុខ \(OABC\) មាន \(OA, OB, OC\) កែងគ្នាពីរៗត្រង់ \(O\) ដោយ \(OA = a, OB = b, OC = c\)។ ចូរស្រាយបញ្ជាក់ថាមាឌ \(V = \frac{1}{6}abc\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់បាតចតុមុខ ៖ យក ΔOAB ជាបាតចតុមុខ (១ ពិន្ទុ) (1 ពិន្ទុ)
គណនាផ្ទៃក្រឡាបាត ៖ ΔOAB កែងត្រង់ O នាំឱ្យ S_OAB = (1/2) x OA x OB = (1/2)ab (១ ពិន្ទុ) (1 ពិន្ទុ)
កំណត់កម្ពស់ ៖ ដោយ OC ⊥ OA និង OC ⊥ OB នាំឱ្យ OC ⊥ (OAB) ដូច្នេះ OC = c ជាកម្ពស់ (១ ពិន្ទុ) (1 ពិន្ទុ)
អនុវត្តរូបមន្តមាឌ ៖ V = (1/3) x S_OAB x OC = (1/3) x (1/2 ab) x c (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ មាឌចតុមុខគឺ V = (1/6)abc ត្រូវបានស្រាយបញ្ជាក់ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'hard', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15844, 'ក្នុងចតុមុខនិយ័ត \(ABCD\) ជ្រុង \(a\)។ ចូរបង្ហាញថាទ្រនុងឈម \(AB\) និង \(CD\) អរតូកូណាល់គ្នា (\(AB \perp CD\))។', NULL, '[]', 0, NULL, 5, 'writing', 'យកចំណុចកណ្តាល M នៃ CD ៖ គូសអង្កត់ AM និង BM (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក AM ⊥ CD ៖ ΔACD សម័ង្ស មាន AM ជាមេដ្យាន នាំឱ្យជាកម្ពស់ AM ⊥ CD (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក BM ⊥ CD ៖ ΔBCD សម័ង្ស មាន BM ជាមេដ្យាន នាំឱ្យជាកម្ពស់ BM ⊥ CD (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក CD ⊥ (ABM) ៖ CD កែងនឹង AM និង BM នាំឱ្យ CD ⊥ (ABM) (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ ដោយ AB ⊂ (ABM) និង CD ⊥ (ABM) នាំឱ្យ CD ⊥ AB ពោលគឺ AB ⊥ CD (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'hard', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15845, 'ចតុមុខ \(OABC\) មាន \(OA, OB, OC\) កែងគ្នាពីរៗត្រង់ \(O\) ហើយ \(OH \perp (ABC)\) ត្រង់ \(H\)។ ចូរស្រាយបញ្ជាក់ថា \(\frac{1}{OH^2} = \frac{1}{OA^2} + \frac{1}{OB^2} + \frac{1}{OC^2}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គូសកម្ពស់បាត ៖ គូស OI ⊥ BC ត្រង់ I ក្នុង ΔOBC នាំឱ្យ 1/OI^2 = 1/OB^2 + 1/OC^2 (១) (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក AI ⊥ BC ៖ តាមទ្រឹស្តីបទបីបន្ទាត់កែង OA ⊥ (OBC) និង OI ⊥ BC នាំឱ្យ AI ⊥ BC (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរក OH ⊥ AI ៖ ក្នុង ΔOAI កែងត្រង់ O មាន OH ជាកម្ពស់គូសលើ AI នាំឱ្យ OH ⊥ (ABC) (១ ពិន្ទុ) (1 ពិន្ទុ)
អនុវត្តក្នុង ΔOAI ៖ 1/OH^2 = 1/OA^2 + 1/OI^2 (២) (១ ពិន្ទុ) (1 ពិន្ទុ)
ជំនួស (១) ចូល (២) ៖ 1/OH^2 = 1/OA^2 + 1/OB^2 + 1/OC^2 ត្រូវបានស្រាយបញ្ជាក់ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'hard', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15846, 'ក្នុងការសាងសង់អគារខ្ពស់ វិស្វករត្រូវធានាថាសសរមេទាំងអស់ត្រូវតែកែងដាច់ខាតនឹងប្លង់កម្រាលបេតុង។ ចូរបកស្រាយពីរបៀបដែលវិស្វករប្រើប្រាស់ឧបករណ៍ឡាស៊ែរ 3D និងទ្រឹស្តីបទបន្ទាត់កែងនឹងប្លង់ដើម្បីផ្ទៀងផ្ទាត់។', NULL, '[]', 0, NULL, 5, 'writing', 'បាញ់កាំរស្មីឡាស៊ែរ ៖ ឧបករណ៍បាញ់កាំរស្មីផ្តេកពីរ orthogonal a និង b លើកម្រាល (a ⊥ b) (១ ពិន្ទុ) (1 ពិន្ទុ)
វាស់ភាពកែងនៃសសរ ៖ វាស់មុំរវាងអ័ក្សសសរ d ជាមួយកាំរស្មី a (ផ្ទៀងផ្ទាត់ d ⊥ a) (១ ពិន្ទុ) (1 ពិន្ទុ)
វាស់ភាពកែងទីពីរ ៖ វាស់មុំរវាងអ័ក្សសសរ d ជាមួយកាំរស្មី b (ផ្ទៀងផ្ទាត់ d ⊥ b) (១ ពិន្ទុ) (1 ពិន្ទុ)
អនុវត្តទ្រឹស្តីបទទី ១ ៖ d ⊥ a និង d ⊥ b ដោយ a និង b ប្រសព្វគ្នា នាំឱ្យ d ⊥ ប្លង់កម្រាល (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ អគារត្រូវបានធានាសុវត្ថិភាពដាច់ខាតចំពោះកម្លាំងសង្កត់បញ្ឈរ និងរញ្ជួយដី (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'pisa', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15847, 'ប៉មទូរគមនាគមន៍មួយមានខ្សែខ្សែកាប ៣ ចងទប់ពីកំពូល \(S\) មកដីត្រង់ \(A, B, C\) ដោយ \(SA = SB = SC\)។ ចូរពន្យល់ពីមូលហេតុដែលជើងប៉ម \(O\) លើដីត្រូវតែជាផ្ចិតរង្វង់ចារឹកក្រៅត្រីកោណ \(ABC\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ប៉មកែងនឹងដី ៖ ប៉មបញ្ឈរ SO ⊥ (ABC) ត្រង់ចំណុច O លើដី (១ ពិន្ទុ) (1 ពិន្ទុ)
ពិនិត្យត្រីកោណកែងទាំងបី ៖ ΔSOA, ΔSOB, ΔSOC សុទ្ធតែជាត្រីកោណកែងត្រង់ O (១ ពិន្ទុ) (1 ពិន្ទុ)
ប្រៀបធៀបអ៊ីប៉ូតេនូស ៖ SA = SB = SC (បម្រាប់ខ្សែស្មើគ្នា) និងមានជ្រុងរួម SO (១ ពិន្ទុ) (1 ពិន្ទុ)
ទាញរកជ្រុងបាតស្មើគ្នា ៖ តាមពីតាក័រ OA = OB = OC = √(SA^2 - SO^2) (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ O ស្មើចម្ងាយពីកំពូលទាំងបី នាំឱ្យ O ជាផ្ចិតរង្វង់ចារឹកក្រៅ ΔABC ធានាលំនឹងស្មើគ្នាគ្រប់ទិស (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'pisa', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15848, 'ដំបូលពហុកីឡដ្ឋានមួយមានរាងជាផ្ទៃកោងដែលត្រូវបានគណនាចំណោលកែងលើប្លង់ដីដើម្បីប៉ាន់ស្មានផ្ទៃក្រឡាស្រូបកម្ដៅថ្ងៃ។ ចូរពន្យល់ពីទំនាក់ទំនងរវាងផ្ទៃដំបូលពិត \(S\) ផ្ទៃចំណោលលើដី \(S''\) និងមុំជម្រាល \(lpha\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់រូបមន្តចំណោលកែង ៖ ផ្ទៃចំណោលកែងលើប្លង់ដីគឺ S'' = S cos(α) (១ ពិន្ទុ) (1 ពិន្ទុ)
វិភាគមុំជម្រាល α ៖ α ជាមុំរវាងប្លង់ដំបូល និងប្លង់ដីផ្តេក (0° ≤ α < 90°) (១ ពិន្ទុ) (1 ពិន្ទុ)
ប្រៀបធៀបផ្ទៃទាំងពីរ ៖ ដោយ 0 < cos(α) ≤ 1 នាំឱ្យ S'' ≤ S ជានិច្ច (១ ពិន្ទុ) (1 ពិន្ទុ)
គណនាផ្ទៃដំបូលពិត ៖ S = S'' / cos(α) ជួយឱ្យវិស្វករប៉ាន់ស្មានបរិមាណសម្ភារៈដំបូលពិតប្រាកដ (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ ចំណោលកែងអនុញ្ញាតឱ្យគណនាថ្លៃដើម និងថាមពលកម្ដៅបានយ៉ាងត្រឹមត្រូវ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'pisa', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15849, 'ក្នុងការផលិតគ្រាប់ឡុកឡាក់ (គូប) ម៉ាស៊ីនស្វ័យប្រវត្តិកាត់ជ្រុងគូបឱ្យមានរាងសុក្រឹត។ ចូរបកស្រាយពីលក្ខណៈធរណីមាត្រនៃគូបដែលធានាឱ្យគ្រាប់ឡុកឡាក់មានឱកាសចេញមុខនីមួយៗស្មើគ្នា \(1/6\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ភាពកែងនៃមុខជាប់គ្នា ៖ មុខជាប់គ្នាពីរៗតែងតែកែងគ្នាបង្កើតបានមុំ 90 ដឺក្រេគ្រប់ទិស (១ ពិន្ទុ) (1 ពិន្ទុ)
ភាពស្របគ្នានៃមុខឈម ៖ មុខឈមទាំងបីគូស្របគ្នា និងមានចម្ងាយស្មើគ្នា a (១ ពិន្ទុ) (1 ពិន្ទុ)
សមភាពនៃផ្ទៃមុខ ៖ មុខទាំង ៦ ជាការេមានផ្ទៃស្មើគ្នាដាច់ខាត S = a^2 (១ ពិន្ទុ) (1 ពិន្ទុ)
ចំណុចកណ្តាលស៊ីមេទ្រី ៖ ផ្ចិតនៃគូបជាចំណុចកណ្តាលស៊ីមេទ្រីនៃម៉ាស ធានាតុល្យភាពទំនាញ (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ ភាពសុក្រឹតនៃធរណីមាត្រធានានូវប្រូបាបស្មើគ្នា 1/6 ចំពោះគ្រប់មុខពេលបោះ (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'pisa', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 15850, 'ប៉មទួរប៊ីនខ្យល់ (Wind Turbine) មានកម្ពស់ \(80	ext{ m}\) និងស្លាបចង្ក្រានប្រវែង \(40	ext{ m}\) វិលក្នុងប្លង់បញ្ឈរមួយ។ ចូរពន្យល់ពីទំនាក់ទំនងធរណីមាត្ររវាងប្លង់រង្វង់រង្វិលនៃស្លាប និងទិសដៅខ្យល់បក់ ដើម្បីទទួលបានថាមពលអតិបរមា។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ប្លង់រង្វិល ៖ ស្លាបចង្ក្រានវិលបង្កើតបានប្លង់រង្វង់ (P) កាំ R = 40 m (១ ពិន្ទុ) (1 ពិន្ទុ)
កំណត់ទិសដៅខ្យល់ ៖ ខ្យល់បក់តាមបន្ទាត់ត្រង់ d សន្មតជាបន្ទាត់ស្របគ្នាក្នុងលំហ (១ ពិន្ទុ) (1 ពិន្ទុ)
លក្ខខណ្ឌថាមពលអតិបរមា ៖ ទិសដៅខ្យល់ d ត្រូវតែកែងនឹងប្លង់រង្វង់រង្វិល d ⊥ (P) (១ ពិន្ទុ) (1 ពិន្ទុ)
ប្រព័ន្ធបង្វិលស្វ័យប្រវត្តិ ៖ ទួរប៊ីនមានប្រព័ន្ធ Yaw drive បង្វិលក្បាលម៉ាស៊ីនឱ្យកែងនឹងខ្យល់ជានិច្ច (១ ពិន្ទុ) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ ភាពកែងគ្នារវាងបន្ទាត់ខ្យល់ និងប្លង់ស្លាបទួរប៊ីនធានាការផ្ទេរថាមពលចលករអតិបរមា (១ ពិន្ទុ) (1 ពិន្ទុ)', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'pisa', 0, '11SC', 'ភាពអរតូកូណាល់ក្នុងលំហ', 'ជំពូកទី 8 : ធរណីមាត្រក្នុងលំហ', NULL, 0);
